#!/usr/bin/env node
/**
 * Emits the server's copy of the policy the preview sandbox seed plans from:
 * functions/_preview_sandbox_tables.json, from security/collections.json and
 * security/storage_paths.json. Cloud Functions deploy only functions/, so
 * functions/_preview_sandbox.js reads this generated file, never the tables.
 *
 * Only the fields the seed planner reads are kept: each collection's kind
 * and its subcollections' serverWritten flag, and each Storage family's
 * paths and migrate flag.
 *
 * It slices the raw collections.json, as written, not the expanded table
 * generate.js passes the other generators: the planner classifies only the
 * subcollections an entry declares itself.
 *
 * Run through security/generate.js (which writes it, and checks it with
 * --check).
 */
'use strict';

const fs = require('fs');
const path = require('path');
const { loadStorageTable } = require('./generate_storage');

const ROOT = path.resolve(__dirname, '..');
const COLLECTIONS_PATH = path.join(__dirname, 'collections.json');
const JSON_PATH = path.join(ROOT, 'functions', '_preview_sandbox_tables.json');

function sortedEntries(obj) {
  return Object.keys(obj || {}).sort().map((key) => [key, obj[key]]);
}

/** { name: { kind?, subcollections? } } for every collection in [table]. */
function collectionsSlice(table) {
  const out = {};
  for (const [name, entry] of sortedEntries(table.collections)) {
    const slim = {};
    if (entry.kind) slim.kind = entry.kind;
    if (entry.subcollections && Object.keys(entry.subcollections).length > 0) {
      slim.subcollections = {};
      for (const [sub, subEntry] of sortedEntries(entry.subcollections)) {
        slim.subcollections[sub] = subEntry?.serverWritten ? { serverWritten: true } : {};
      }
    }
    out[name] = slim;
  }
  return out;
}

/** { name: { paths, migrate? } } for every family in [storageTable]. */
function familiesSlice(storageTable) {
  const out = {};
  for (const [name, family] of sortedEntries(storageTable.families)) {
    const slim = { paths: Array.isArray(family.paths) ? [...family.paths] : [] };
    if (family.migrate) slim.migrate = true;
    out[name] = slim;
  }
  return out;
}

function renderJson(table, storageTable) {
  return `${JSON.stringify({
    comment: 'GENERATED by security/generate.js (security/generate_preview_sandbox.js) from security/collections.json and security/storage_paths.json. Do not edit: change the tables and run `node security/generate.js`.',
    collections: collectionsSlice(table),
    families: familiesSlice(storageTable),
  }, null, 2)}\n`;
}

function loadRawCollectionsTable() {
  return JSON.parse(fs.readFileSync(COLLECTIONS_PATH, 'utf8'));
}

/** Writes (or with --check, verifies) the server's copy. */
function main(argv = [], { table = loadRawCollectionsTable(), storageTable = loadStorageTable() } = {}) {
  const next = renderJson(table, storageTable);
  const current = fs.existsSync(JSON_PATH) ? fs.readFileSync(JSON_PATH, 'utf8') : null;
  if (argv.includes('--check')) {
    if (current !== next) {
      console.error(`${path.relative(ROOT, JSON_PATH)} is out of date with security/collections.json or security/storage_paths.json. Run \`node security/generate.js\` and commit the result.`);
      process.exitCode = 1;
    }
    return;
  }
  if (current !== next) {
    fs.writeFileSync(JSON_PATH, next);
    console.log(`${path.relative(ROOT, JSON_PATH)} regenerated.`);
  }
}

module.exports = { JSON_PATH, loadRawCollectionsTable, collectionsSlice, familiesSlice, renderJson, main };
